def is_safe(q, row, col):
    for i in range(row):
        if q[i] == col or abs(q[i] - col) == abs(i - row):
            return False
    return True

def solve_n_queens(n, fixed_q):
    q = [-1] * n
    for row, col in fixed_q.items():
        q[row] = col

    def backtrack(row):
        if row == n:
            return True

        if q[row] != -1:
            # Check if the fixed position is valid
            if not is_safe(q, row, q[row]):
                return False
            return backtrack(row + 1)

        for col in range(n):
            if is_safe(q, row, col):
                q[row] = col
                if backtrack(row + 1):
                    return True
                q[row] = -1
        return False

    if backtrack(0):
        return q
    else:
        return None

fixed_q = {1: 12, 11: 1}
solution = solve_n_queens(13, fixed_q)
print(solution)
